'use client';

import { useState, useEffect } from 'react';
import { SummaryCard } from '@/components/dashboard/summary-card';
import { RecentInvoices } from '@/components/dashboard/recent-invoices';

export default function DashboardPage() {
  const [invoiceStats, setInvoiceStats] = useState({
    draft: 0,
    validated: 0,
    posted: 0,
    failed: 0,
  });

  const [recentInvoices, setRecentInvoices] = useState<Array<{
    id: string;
    number: string;
    date: string;
    amount: number;
    status: 'draft' | 'validated' | 'posted' | 'failed';
  }>>([]);

  useEffect(() => {
    // In a real app, fetch stats and recent invoices from the API
    // For now, we'll simulate with mock data
    setInvoiceStats({
      draft: 5,
      validated: 12,
      posted: 43,
      failed: 2,
    });

    setRecentInvoices([
      { id: 'INV-001', number: 'INV-001', date: '2023-10-15', amount: 15000, status: 'posted' },
      { id: 'INV-002', number: 'INV-002', date: '2023-10-16', amount: 8500, status: 'validated' },
      { id: 'INV-003', number: 'INV-003', date: '2023-10-17', amount: 12000, status: 'draft' },
      { id: 'INV-004', number: 'INV-004', date: '2023-10-18', amount: 22500, status: 'failed' },
    ]);
  }, []);

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold text-gray-900">Dashboard</h1>
        <p className="mt-2 text-gray-600">Welcome back! Here's what's happening with your invoices.</p>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-4">
        <SummaryCard
          title="Draft"
          count={invoiceStats.draft}
          icon="📝"
          color="bg-blue-500"
        />
        <SummaryCard
          title="Validated"
          count={invoiceStats.validated}
          icon="✅"
          color="bg-green-500"
        />
        <SummaryCard
          title="Posted"
          count={invoiceStats.posted}
          icon="📤"
          color="bg-purple-500"
        />
        <SummaryCard
          title="Failed"
          count={invoiceStats.failed}
          icon="❌"
          color="bg-red-500"
        />
      </div>

      {/* Recent Invoices */}
      <div className="mt-8">
        <h2 className="text-xl font-semibold text-gray-900">Recent Invoices</h2>
        <RecentInvoices invoices={recentInvoices} />
      </div>
    </div>
  );
}